from binascii import unhexlify
import string

def read_raw_file(path):
    with open(path, 'rb') as f:
        return bytearray(f.read())

def xor_bytes(a, b):
    return bytearray([x ^ y for x, y in zip(a, b)])

def print_ascii(xorval, off=0):
    output = ''
    for i, b in enumerate(xorval):
        if chr(b) in string.printable:
            output += chr(b)
        else:
            output += '.'
    print(f"Offset {off:02x}: {output}")

def cribdrag(xor, crib):
    n = len(crib)
    crib_bytes = crib.encode('ascii')
    for i in range(len(xor) - n + 1):
        p = xor[i:i+n]
        attempt = xor_bytes(crib_bytes, p)
        printable = ''.join([chr(c) if chr(c) in string.printable else '.' for c in attempt])
        # Show as possible plaintext for c2 or c4 at offset.
        print(f"Offset {i:02x} | {crib}: {printable}")

def main():
    c2 = read_raw_file('/home/ctfplayer/ctf_files/c2.bin.raw')
    c4 = read_raw_file('/home/ctfplayer/ctf_files/c4.bin.raw')
    xor = xor_bytes(c2, c4)
    print("--- XOR (printable) ---")
    print_ascii(xor)
    # Found 'sage' yielded good output near offset 0x20, try some cribs
    for word in ['sage', 'Message', 'token', 'token:', 'secret', 'reward', ':', 'status', 'flag', 'win', 'flag:']:
        cribdrag(xor, word)

if __name__ == '__main__':
    main()

# Try using 'flag:', 'Message', 'token:' at known offsets of c4, XOR with c4 to get keystream, then apply to c2 and seek readable/decrypt tokens
def read_raw(path):
    with open(path, 'rb') as f:
        return bytearray(f.read())

def recover_keystream(ciphertext, crib, offset):
    crib_bytes = crib.encode()
    return [ciphertext[offset+i] ^ crib_bytes[i] for i in range(len(crib_bytes))]

def apply_keystream(other_cipher, keystream, offset):
    return bytes([other_cipher[offset+i] ^ k for i,k in enumerate(keystream)])

def main():
    c2 = read_raw('/home/ctfplayer/ctf_files/c2.bin.raw')
    c4 = read_raw('/home/ctfplayer/ctf_files/c4.bin.raw')
    pairs = [
        (c4, 'flag', 8), (c4, 'flag:', 8), # 'flag' at 0x8
        (c4, 'Message', 8), (c4, 'Message:', 8),
        (c4, 'token', 8), (c4, 'token:', 8),
        (c4, 'flag', 40), (c4, 'flag:', 40), # more flag at 0x28
    ]
    for ct, crib, offset in pairs:
        ks = recover_keystream(ct, crib, offset)
        dec = apply_keystream(c2, ks, offset)
        print(f"Crib '{crib}' @ {offset:02x} yields in c2: {dec}")
    # Now try for c2 as base, apply crib to c2, and decode c4
    pairs = [
        (c2, 'flag', 8), (c2, 'flag:', 8),
        (c2, 'Message', 8), (c2, 'Message:', 8),
        (c2, 'token', 8), (c2, 'token:', 8),
        (c2, 'flag', 40), (c2, 'flag:', 40),
    ]
    for ct, crib, offset in pairs:
        ks = recover_keystream(ct, crib, offset)
        dec = apply_keystream(c4, ks, offset)
        print(f"(c2 as base) Crib '{crib}' @ {offset:02x} yields in c4: {dec}")

if __name__ == '__main__':
    main()

