import glob
import os

PLAIN_CRIBS = [
    (8, 'flag:'),
    (8, 'Message:'),
    (8, 'token:'),
    (8, 'flag'),
    (28, 'flag:'),
    (28, 'flag'),
]

def read_raw(path):
    with open(path, 'rb') as f:
        return bytearray(f.read())

def xor_crib(cipher, crib, offset):
    return [cipher[offset+i] ^ crib[i] for i in range(len(crib))]

def decrypt_keystream(cipher, ks, offset):
    try:
        pt = bytes([cipher[offset+i] ^ ks[i] for i in range(len(ks))])
        # Only printable ASCII
        if all(chr(x) in set("0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ:{}_-:|/.(),'\" ") for x in pt):
            return pt.decode()
        else:
            return pt.hex()
    except Exception:
        return None


def main():
    cpaths = sorted([x for x in glob.glob('/home/ctfplayer/ctf_files/*.bin.raw')])
    print("Ciphertext set:", cpaths)
    for offset, cribstr in PLAIN_CRIBS:
        crib = cribstr.encode()
        print(f"\n------ Keystream from crib '{cribstr}' at {offset:x} ------")
        for base in cpaths:
            base_bytes = read_raw(base)
            ks = xor_crib(base_bytes, crib, offset)
            print(f"\nExtracting keystream @ {base}, crib '{cribstr}', @ {offset:x}: {ks}")
            for cfile in cpaths:
                cbytes = read_raw(cfile)
                candidate = decrypt_keystream(cbytes, ks, offset)
                print(f"{os.path.basename(cfile)} offset {offset:02x} using keystream from {os.path.basename(base)} '{cribstr}': {candidate}")

if __name__ == '__main__':
    main()

